property.value:
umask 0027

export HADOOP_HOME=${HADOOP_HOME:-{{hadoop_home_shell}}}
export HIVE_HOME=${HIVE_HOME:-{{hive_home_shell}}}
export HIVE_CONF_DIR=${HIVE_CONF_DIR:-{{hive_conf_dir_shell}}}
export METASTORE_PORT={{hive_metastore_port}}

if [ "${SERVICE:-}" = "metastore" ]; then
  export HADOOP_HEAPSIZE={{hive_metastore_heapsize}}
  if "$JAVA_HOME/bin/java" -version 2>&1 | grep -q 'version "17'; then
    export HADOOP_OPTS="${HADOOP_OPTS:-} -XX:+UseG1GC -Xlog:gc*:file={{hive_log_dir}}/hivemetastore-gc.log:time,uptime,level,tags:filecount=10,filesize=10M -Dhive.log.dir={{hive_log_dir}} -Dhive.log.file=hivemetastore.log"
  else
    export HADOOP_OPTS="${HADOOP_OPTS:-} -Dhive.log.dir={{hive_log_dir}} -Dhive.log.file=hivemetastore.log"
  fi
elif [ "${SERVICE:-}" = "hiveserver2" ]; then
  export HADOOP_HEAPSIZE={{hive_heapsize}}
  if "$JAVA_HOME/bin/java" -version 2>&1 | grep -q 'version "17'; then
    export HADOOP_OPTS="${HADOOP_OPTS:-} -XX:+UseG1GC -Xlog:gc*:file={{hive_log_dir}}/hiveserver2-gc.log:time,uptime,level,tags:filecount=10,filesize=10M -Dhive.log.dir={{hive_log_dir}} -Dhive.log.file=hiveserver2.log"
  else
    export HADOOP_OPTS="${HADOOP_OPTS:-} -Dhive.log.dir={{hive_log_dir}} -Dhive.log.file=hiveserver2.log"
  fi
else
  export HADOOP_HEAPSIZE={{hive_heapsize}}
fi

{% if security_enabled %}
export HADOOP_OPTS="${HADOOP_OPTS:-} -Dzookeeper.sasl.client.username={{zk_principal_user}}"
{% endif %}

export HADOOP_CLIENT_OPTS="${HADOOP_CLIENT_OPTS:-} -Xms${HADOOP_HEAPSIZE}m -Xmx${HADOOP_HEAPSIZE}m"
{% if heap_dump_enabled %}
export HADOOP_CLIENT_OPTS="${HADOOP_CLIENT_OPTS} -XX:+HeapDumpOnOutOfMemoryError -XX:HeapDumpPath={{heap_dump_path}}"
{% endif %}

if [ -z "${HIVE_AUX_JARS_PATH:-}" ]; then
  if [ -d {{hive_hcatalog_home_shell}} ]; then
    export HIVE_AUX_JARS_PATH={{hive_hcatalog_home_shell}}/share/hcatalog/hive-hcatalog-core-*.jar
  else
    export HIVE_AUX_JARS_PATH={{hive_hcatalog_home_shell}}/share/hcatalog/hcatalog-core.jar
  fi
fi
